def find_possible_message(t):
    n = len(t)
    for i in range(1, n // 2 + 1):
        # Check if the first i characters match the last i characters
        if t[:i] == t[-i:]:
            candidate = t[:-i]
            overlap = 0
            # Find the maximum overlap
            while overlap < i and t[-i + overlap] == t[overlap]:
                overlap += 1
            # Ensure the overlap is positive and less than i
            if overlap > 0 and overlap < i:
                # Check if the candidate repeated with the overlap matches the original message
                if candidate + candidate[overlap:] == t:
                    return "YES", candidate
    return "NO", ""

